declare
  root_id text;
  root_entity text;
begin
  root_id := new."id";
  select "entity" into root_entity from "Entity" where "id" = root_id;
  if not found then
    return null;
  end if;
  case root_entity
    when 'User' then
        if not exists (select 1 from "User" where "id" = root_id) then
          raise exception 'incomplete root row % for entity %', root_id, root_entity;
        end if;
    when 'Role' then
        if not exists (select 1 from "Role" where "id" = root_id) then
          raise exception 'incomplete root row % for entity %', root_id, root_entity;
        end if;
    when 'ExternalIdentity' then
        if not exists (select 1 from "ExternalIdentity" where "id" = root_id) then
          raise exception 'incomplete root row % for entity %', root_id, root_entity;
        end if;
    when 'Note' then
        if not exists (select 1 from "Note" where "id" = root_id) then
          raise exception 'incomplete root row % for entity %', root_id, root_entity;
        end if;
    else
      raise exception 'unknown concrete entity %', root_entity;
  end case;
  return new;
end

